using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Animation;
using System.Windows.Input;
using HD2ModManager.Controls.Lists;
using HD2ModManager.ViewModels;

namespace HD2ModManager.Views
{
    // This class is generated by XAML compilation
    public partial class LibraryPageView : UserControl
    {
        public LibraryPageView()
        {
            InitializeComponent();
            Loaded += LibraryPageView_Loaded;
            Loaded += (_, _) =>
            {
                ModListExternalProfileRemovalCoordinator.RegisterTarget(LibraryModList);
                // 文案比面板的通用文案具体（带上主体名），所以这里给一个工厂。
                LibraryModList.RelationshipDropHintFactory = DescribeRelationshipDrop;
            };
            Unloaded += (_, _) => ModListExternalProfileRemovalCoordinator.UnregisterTarget(LibraryModList);
        }

        private void LibraryPageView_Loaded(object sender, RoutedEventArgs e)
        {
            EnsureVM();
        }
        public LibraryPageViewModel? VM { get; private set; }

        private void EnsureVM()
        {
            if (DataContext is LibraryPageViewModel existing)
            {
                VM = existing;
                return;
            }

            if (VM == null)
            {
                var shell = (Application.Current?.MainWindow as MainWindow)?.DataContext as HD2ModManager.ViewModels.ShellViewModel;
                if (shell == null) return;
                VM = new LibraryPageViewModel(shell.LibraryService, shell.Selection, shell.ProfileService);
                DataContext = VM;
            }
        }

        private void OnRowActionInvoked(object? sender, ModListRowActionEventArgs e)
        {
            EnsureVM();
            if (VM is null || e.Item is not ModCardViewModel card) return;
            ClearTransientSelection();
            var shell = (Application.Current?.MainWindow as MainWindow)?.DataContext as ShellViewModel;
            switch (e.Action)
            {
                case ModListRowAction.Rename:
                    shell?.BeginBottomBarNameEdit(card.Mod.Guid, card.Mod.Name);
                    break;
                case ModListRowAction.Details:
                    shell?.OpenModDetailsFromPage(VM, card.Mod.Guid);
                    break;
                case ModListRowAction.AddToProfile:
                    VM.AddToProfileCommand.Execute(card);
                    break;
                case ModListRowAction.ToggleDecoration:
                    VM.ToggleDecorationCommand.Execute(card);
                    break;
                case ModListRowAction.ExportMod:
                    shell?.BeginModExport(card.Mod.Guid, card.Mod.Name);
                    break;
                case ModListRowAction.OpenFolder:
                    VM.OpenFolderCommand.Execute(card);
                    break;
                case ModListRowAction.DeleteFromLibrary:
                    VM.RemoveCommand.Execute(card);
                    break;
            }
        }

        private void OnOpenDetailsOnRightClick(object sender, ModListRowEventArgs e)
        {
            if (e.Item is not ModCardViewModel card) return;
            var shell = (Application.Current?.MainWindow as MainWindow)?.DataContext as ShellViewModel;
            shell?.OpenModDetailsFromPage(VM, card.Mod.Guid);
        }

        private void OnListBackgroundClick(object? sender, EventArgs e)
        {
            ClearTransientSelection();
        }

        private static void ClearTransientSelection()
        {
            if (Application.Current?.MainWindow?.DataContext is ShellViewModel shell)
                shell.ClearTransientSelection();
        }

        private void OnToggleOutdatedFilterClick(object sender, RoutedEventArgs e)
        {
            EnsureVM();
            if (VM is not null) VM.ShowOnlyOutdated = !VM.ShowOnlyOutdated;
        }

        private void OnSelectionRequested(object? sender, ModListSelectionRequestEventArgs e)
        {
            EnsureVM();
            VM?.ApplySelection(e.SelectedKeys);
        }

        private async void OnKeyboardCommandRequested(object? sender, ModListKeyboardCommandEventArgs e)
        {
            EnsureVM();
            if (VM is null) return;
            var shell = (Application.Current?.MainWindow as MainWindow)?.DataContext as ShellViewModel;
            switch (e.Command)
            {
                case ModListKeyboardCommand.Rename when e.Item is ModCardViewModel card:
                    ClearTransientSelection();
                    shell?.BeginBottomBarNameEdit(card.Mod.Guid, card.Mod.Name);
                    break;
                case ModListKeyboardCommand.OpenDetails when e.Item is ModCardViewModel card:
                    shell?.OpenModDetailsFromPage(VM, card.Mod.Guid);
                    break;
                case ModListKeyboardCommand.Delete:
                case ModListKeyboardCommand.DeleteFromLibrary:
                    if (shell is not null) await shell.DeleteModsFromLibraryAsync(e.SelectedKeys);
                    break;
            }
        }

        private async void OnExternalProfileRemovalRequested(object? sender, ModListExternalProfileDropEventArgs e)
        {
            if (Application.Current?.MainWindow?.DataContext is ShellViewModel shell)
                await shell.RemoveModsFromSelectedProfileAsync(e.SelectedKeys);
        }

        private void OnToggleDecorationFilterClick(object sender, RoutedEventArgs e)
        {
            EnsureVM();
            if (VM is not null) VM.ShowDecorations = !VM.ShowDecorations;
        }

        private void OnToggleOptionFilterClick(object sender, RoutedEventArgs e)
        {
            EnsureVM();
            if (VM is not null) VM.ShowOptions = !VM.ShowOptions;
        }

        // 叠层、命中、淡入淡出已经由面板负责；这里只剩"放下之后做什么"和一句文案。
        private void OnRelationshipDropRequested(object? sender, ModListRelationshipDropEventArgs e)
        {
            if (e.Operation != ModRelationshipDragOperation.RemoveOptionParent
                || string.IsNullOrWhiteSpace(e.SourceHostId))
                return;
            if (Application.Current?.MainWindow?.DataContext is ShellViewModel shell)
                _ = shell.RemoveOptionsFromHostAsync(e.SourceHostId, e.SelectedKeys);
        }

        private static ModListDropHint DescribeRelationshipDrop(ModRelationshipDragPayload payload)
        {
            var shell = Application.Current?.MainWindow?.DataContext as ShellViewModel;
            var hostName = string.IsNullOrWhiteSpace(payload.SourceHostId)
                ? "当前主体"
                : shell?.LibraryService.Get(payload.SourceHostId)?.Name ?? "当前主体";
            return new ModListDropHint(
                "释放以解除选项关系",
                $"将 {payload.SelectedKeys.Count} 个选项从“{hostName}”移出");
        }

    }
}
